package com.workworth.earnings.api; import com.workworth.earnings.api.dto.*; import com.workworth.earnings.application.*; import com.workworth.earnings.domain.EarningPeriod; import java.time.LocalDate; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/earnings") public class EarningsController {private final ActiveEarningProjectionService projections;private final EarningPeriodService periods;private final EarningQueryService queries;public EarningsController(ActiveEarningProjectionService p,EarningPeriodService periods,EarningQueryService q){projections=p;this.periods=periods;queries=q;}@GetMapping("/current/projection")public ResponseEntity<EarningProjectionResponse> projection(){return ResponseEntity.ok(EarningProjectionResponse.from(projections.current()));}@GetMapping("/periods/{context}")public ResponseEntity<EarningPeriodResponse> period(@PathVariable EarningPeriod context){return ResponseEntity.ok(EarningPeriodResponse.from(periods.summarize(context)));}@GetMapping("/workdays/{date}")public ResponseEntity<EarningResponse> workday(@PathVariable LocalDate date){return ResponseEntity.ok(EarningResponse.from(queries.byDate(date)));}@GetMapping("/history")public ResponseEntity<List<EarningResponse>> history(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination parameters.");return ResponseEntity.ok(queries.history(page,size).stream().map(EarningResponse::from).toList());}@GetMapping("/workdays/{date}/corrections")public ResponseEntity<List<EarningCorrectionResponse>> corrections(@PathVariable LocalDate date){return ResponseEntity.ok(queries.corrections(date).stream().map(EarningCorrectionResponse::from).toList());}}
